<?php
declare(strict_types=1);
namespace Hostider\Support\UI;
use Hostider\Core\{Id,Idempotency,Validation,CanonicalJson};
use Hostider\Core\Http\HttpError;
use Hostider\Core\Security\{Audit,AuditEvent};
use Hostider\Support\{Access,Service};
use Hostider\Support\Advanced\Common;
final readonly class StateStore
{
    public function __construct(public Context $x){}
    public function ticket(array $u,array $s,string $ctx,array $p): array
    {
        if(!in_array($p['kind'],['reply','note'],true)||($ctx==='client'&&$p['kind']!=='reply')){throw new HttpError(403,'SUPPORT_DRAFT_KIND_FORBIDDEN');}return $this->x->m->access->ticket($u,$s,Access::id($p['ticket_id']),$p['kind']==='note'?'support.ticket.internal_note':'support.ticket.reply');
    }
    public function draft(array $u,array $s,array $t,string $kind,bool $lock=false): array|false{return $this->x->m->c->db->execute('SELECT * FROM support_ui_drafts WHERE user_id=? AND session_id=? AND ticket_id=? AND customer_id=? AND kind=? AND expires_at>UTC_TIMESTAMP(6)'.($lock?' FOR UPDATE':''),[$u['id'],$s['id'],$t['id'],$t['customer_id'],$kind])->fetch();}
    private function filterAllowed(array $u,array $s,string $ctx,array $p): bool
    {
        $deps=$this->x->departments($u,$s);if(isset($p['department_id'])){$deps=array_values(array_filter($deps,fn($r)=>$r['id']===$p['department_id']));}if($deps===[]){return false;}if($ctx==='admin'&&isset($p['customer_id'])){foreach($deps as $d){if($this->x->permission($u,$s,['customer_id'=>$p['customer_id'],'department_id'=>$d['id']],'support.ticket.view')){return true;}}return false;}return true;
    }
    public function view(string $ref,string $ctx,string $view,array $p): array
    {
        Validation::fields($p,$view==='draft'?['ticket_id','kind']:[], $view==='draft'?['ticket_id','kind']:[]);return $this->x->run($ref,$ctx,function($u,$s)use($ctx,$view,$p){$m=$this->x->m;if($view==='draft'){$t=$this->ticket($u,$s,$ctx,$p);$r=$this->draft($u,$s,$t,$p['kind']);if(!$r){return ['draft'=>null];}return ['draft'=>['id'=>$r['id'],'kind'=>$r['kind'],'body'=>$m->crypto->decrypt($r['body_encrypted'],'support-ui-draft:'.$r['id']),'version'=>(int)$r['version'],'base_version'=>(int)$r['base_version'],'expires_at'=>$r['expires_at'],'stale'=>(int)$r['base_version']!==(int)$t['version']]];}$out=[];foreach($m->c->db->execute('SELECT * FROM support_ui_filters WHERE user_id=? AND session_id=? AND context=? AND expires_at>UTC_TIMESTAMP(6) ORDER BY id LIMIT 10',[$u['id'],$s['id'],$ctx])->fetchAll() as $r){$spec=json_decode($m->crypto->decrypt($r['spec_encrypted'],'support-ui-filter:'.$r['id']),true,16,JSON_THROW_ON_ERROR);if($this->filterAllowed($u,$s,$ctx,$spec)){$out[]=['id'=>$r['id'],'version'=>(int)$r['version'],'label'=>$m->crypto->decrypt($r['label_encrypted'],'support-ui-label:'.$r['id']),'filter'=>$spec];}}return ['filters'=>$out,'scope'=>'CURRENT_SESSION','limit'=>10];});
    }
    public function command(string $ref,string $ctx,string $action,array $p,string $key,string $trace): array
    {
        $this->x->m->gate();$keys=match($action){'draft-save'=>['ticket_id','kind','body','base_version','version'],'draft-delete'=>['ticket_id','kind','version'],'filter-save'=>['id','version','label','filter'],'filter-delete'=>['id','version'],'presence'=>['ticket_id'],default=>throw new HttpError(422,'SUPPORT_STATE_ACTION_INVALID')};Validation::fields($p,$keys,$action==='filter-save'?['version','label','filter']:$keys);if(isset($p['id'])){Access::id($p['id']);}if(isset($p['version'])){Common::version($p['version'],true);}if($action==='draft-save'){Common::text($p['body'],16000,true);Service::version($p['base_version']);}if($action==='filter-save'){$p['filter']=Views::filters(Common::object($p['filter']),$ctx,false);Common::text($p['label'],48);}if($action==='presence'&&$ctx!=='admin'){throw new HttpError(403,'STAFF_REQUIRED');}
        $work=function(bool $replay)use($ref,$ctx,$action,$p,$trace){return $this->x->run($ref,$ctx,function($u,$s)use($ctx,$action,$p,$trace,$replay){$m=$this->x->m;$db=$m->c->db;$t=null;if(str_starts_with($action,'draft-')){$t=$this->ticket($u,$s,$ctx,$p);}if($action==='presence'){$t=$m->access->ticket($u,$s,Access::id($p['ticket_id']));}if($action==='filter-save'&&!$this->filterAllowed($u,$s,$ctx,$p['filter'])){throw new HttpError(404,'SUPPORT_FILTER_SCOPE');}if($replay){return [];}
            if($action==='presence'){$db->execute('DELETE FROM support_ui_presence WHERE session_id=? AND observed_at<TIMESTAMPADD(SECOND,-120,UTC_TIMESTAMP(6))',[$s['id']]);if((int)$db->execute('SELECT COUNT(*) FROM support_ui_presence WHERE session_id=?',[$s['id']])->fetchColumn()>=8&&!$db->execute('SELECT 1 FROM support_ui_presence WHERE session_id=? AND ticket_id=?',[$s['id'],$t['id']])->fetchColumn()){throw new HttpError(409,'SUPPORT_PRESENCE_LIMIT');}$db->execute('INSERT INTO support_ui_presence VALUES (?,?,?,?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE observed_at=VALUES(observed_at)',[$s['id'],$u['id'],$t['id'],$t['customer_id']]);return ['approximate'=>true,'expires_in'=>120];}
            if($t!==null){$db->execute('DELETE FROM support_ui_drafts WHERE session_id=? AND expires_at<=UTC_TIMESTAMP(6)',[$s['id']]);$r=$this->draft($u,$s,$t,$p['kind'],true);if((int)($r['version']??0)!==$p['version']){throw new HttpError(409,'SUPPORT_DRAFT_VERSION_CONFLICT');}if($action==='draft-delete'){if($r){$db->execute('DELETE FROM support_ui_drafts WHERE id=?',[$r['id']]);}return ['deleted'=>true];}if($p['base_version']>(int)$t['version']){throw new HttpError(409,'SUPPORT_VERSION_CONFLICT');}$id=$r['id']??Id::uuid();$body=$m->crypto->encrypt($p['body'],'support-ui-draft:'.$id);if(!$r){if((int)$db->execute('SELECT COUNT(*) FROM support_ui_drafts WHERE session_id=?',[$s['id']])->fetchColumn()>=32){throw new HttpError(409,'SUPPORT_DRAFT_LIMIT');}$db->execute('INSERT INTO support_ui_drafts(id,user_id,session_id,customer_id,ticket_id,kind,body_encrypted,base_version,expires_at) VALUES (?,?,?,?,?,?,?,?,TIMESTAMPADD(SECOND,1800,UTC_TIMESTAMP(6)))',[$id,$u['id'],$s['id'],$t['customer_id'],$t['id'],$p['kind'],$body,$p['base_version']]);}else{$db->execute('UPDATE support_ui_drafts SET body_encrypted=?,base_version=?,version=version+1,expires_at=TIMESTAMPADD(SECOND,1800,UTC_TIMESTAMP(6)) WHERE id=?',[$body,$p['base_version'],$id]);}(new Audit($db))->record($m->access->actor($u,$s),AuditEvent::SupportChanged,$id,$trace);return ['id'=>$id,'version'=>$p['version']+1,'base_version'=>$p['base_version'],'stale'=>$p['base_version']!==(int)$t['version']];}
            $db->execute('DELETE FROM support_ui_filters WHERE session_id=? AND expires_at<=UTC_TIMESTAMP(6)',[$s['id']]);$id=$p['id']??Id::uuid();$r=$db->execute('SELECT * FROM support_ui_filters WHERE id=? FOR UPDATE',[$id])->fetch();if($r&&($r['user_id']!==$u['id']||$r['session_id']!==$s['id']||$r['context']!==$ctx)){throw new HttpError(404,'SUPPORT_FILTER_NOT_FOUND');}if((int)($r['version']??0)!==$p['version']){throw new HttpError(409,'SUPPORT_FILTER_VERSION_CONFLICT');}if($action==='filter-delete'){if($r){$db->execute('DELETE FROM support_ui_filters WHERE id=?',[$id]);}return ['deleted'=>true];}if(!$r&&(int)$db->execute('SELECT COUNT(*) FROM support_ui_filters WHERE session_id=?',[$s['id']])->fetchColumn()>=10){throw new HttpError(409,'SUPPORT_FILTER_LIMIT');}$label=$m->crypto->encrypt($p['label'],'support-ui-label:'.$id);$spec=$m->crypto->encrypt(CanonicalJson::encode($p['filter']),'support-ui-filter:'.$id);if($r){$db->execute('UPDATE support_ui_filters SET label_encrypted=?,spec_encrypted=?,version=version+1,expires_at=TIMESTAMPADD(DAY,7,UTC_TIMESTAMP(6)) WHERE id=?',[$label,$spec,$id]);}else{$db->execute('INSERT INTO support_ui_filters(id,user_id,session_id,context,label_encrypted,spec_encrypted,expires_at) VALUES (?,?,?,?,?,?,TIMESTAMPADD(DAY,7,UTC_TIMESTAMP(6)))',[$id,$u['id'],$s['id'],$ctx,$label,$spec]);}(new Audit($db))->record($m->access->actor($u,$s),AuditEvent::SupportChanged,$id,$trace);return ['id'=>$id,'version'=>$p['version']+1];});};return (new Idempotency($this->x->m->c->db))->run($ref,'support-ui:'.$ctx.':'.$action,$key,['hmac'=>$this->x->m->hash($p)],fn()=>$work(false),fn()=>$work(true));
    }
    public function presence(string $ref,array $p): array
    {
        Validation::fields($p,['ticket_id'],['ticket_id']);return $this->x->run($ref,'admin',function($u,$s)use($p){$m=$this->x->m;$t=$m->access->ticket($u,$s,Access::id($p['ticket_id']));$rows=$m->c->db->execute("SELECT s.native_reference FROM support_ui_presence p JOIN identity_sessions s ON s.id=p.session_id WHERE p.ticket_id=? AND p.customer_id=? AND p.observed_at>TIMESTAMPADD(SECOND,-120,UTC_TIMESTAMP(6)) AND s.context='admin' AND s.revoked_at IS NULL AND s.expires_at>UTC_TIMESTAMP(6) ORDER BY p.user_id LIMIT 64",[$t['id'],$t['customer_id']])->fetchAll();$ids=[];foreach($rows as $r){try{$rs=$m->c->identity->repository->session($r['native_reference'],'admin');$ru=$m->c->identity->repository->user($rs['user_id']);$m->c->identity->repository->validate($ru,$rs);$m->access->require($ru,$rs,$t['customer_id'],$t['department_id']);$ids[$ru['id']]=true;}catch(HttpError){}}return ['viewers'=>count($ids),'approximate'=>true,'window_seconds'=>120,'typing'=>'NOT_TRACKED'];});
    }
}
